const AUTH_ERR={invalid_credentials:'<strong>Falsche Anmeldedaten:</strong> E-Mail oder Passwort stimmt nicht. Bitte prüfen (auch Groß- und Kleinschreibung) – oder <a href="/auth/forgot">Passwort zurücksetzen</a>.',email_not_confirmed:'Bitte zuerst Ihre E-Mail-Adresse bestätigen (Link in der Bestätigungs-Mail, auch im Spam-Ordner nachsehen). <button type="button" class="link-btn" id="resendConfirm">Bestätigungs-Mail erneut senden</button>',over_request_rate_limit:'Zu viele Versuche. Bitte einige Minuten warten und erneut versuchen.',over_email_send_rate_limit:'Es wurden gerade zu viele E-Mails angefordert. Bitte einige Minuten warten.',user_already_exists:'Für diese E-Mail-Adresse gibt es bereits ein Konto. Bitte <a href="/auth/login">anmelden</a> oder das <a href="/auth/forgot">Passwort zurücksetzen</a>.',email_exists:'Für diese E-Mail-Adresse gibt es bereits ein Konto. Bitte <a href="/auth/login">anmelden</a>.',weak_password:'Das Passwort ist zu schwach. Bitte mindestens 8 Zeichen mit Buchstaben und Zahlen wählen.',validation_failed:'Bitte E-Mail-Adresse und Passwort prüfen.'};
const authErr=(d,fallback)=>{const c=d&&(d.error_code||d.code);const k=typeof c==='string'?c:'';if(AUTH_ERR[k])return AUTH_ERR[k];const t=String((d&&(d.error_description||d.msg||d.message))||'');if(/invalid login credentials/i.test(t))return AUTH_ERR.invalid_credentials;if(/email not confirmed/i.test(t))return AUTH_ERR.email_not_confirmed;if(/already registered|already exists/i.test(t))return AUTH_ERR.user_already_exists;if(/rate limit|too many/i.test(t))return AUTH_ERR.over_request_rate_limit;if(/password should/i.test(t))return AUTH_ERR.weak_password;return fallback};
const msgHtml=(h,c='error')=>{const e=document.querySelector('#authMessage');if(!e)return;e.hidden=false;e.innerHTML=h;e.className='auth-message '+c;const rb=document.getElementById('resendConfirm');if(rb)rb.onclick=async()=>{const em=(document.querySelector('#email')||{}).value||'';if(!em)return;rb.disabled=true;try{const im=await iaMail({action:'resend',email:em.trim().toLowerCase()});if(!im)await api('/auth/v1/resend?redirect_to='+encodeURIComponent(location.origin+'/auth/login'),{method:'POST',body:JSON.stringify({type:'signup',email:em.trim().toLowerCase()})});msg('Bestätigungs-Mail wurde erneut gesendet. Bitte Posteingang und Spam-Ordner prüfen.','success')}catch{msg('Senden fehlgeschlagen. Bitte später erneut versuchen.','error')}}};
