async function billing(){const box=document.getElementById('billingBody');if(!box)return;const H={Authorization:'Bearer '+(get()?.access_token||'')};let c;try{c=await(await fetch('/api/billing/config',{cache:'no-store'})).json()}catch{c={enabled:false}}
if(!c.enabled){box.innerHTML='<p>Kostenloser Zugang aktiv. Die Kreditmappe können Sie bereits als Vorschau mit Wasserzeichen erstellen. Bezahlte Angebote werden buchbar, sobald die Zahlungsabwicklung startet.</p><p><a class="btn btn-outline" href="#angebot">Angebote und Preise ansehen</a></p>';return}
const q=new URLSearchParams(location.search);let st;try{const r=await fetch('/api/billing/status',{headers:H,cache:'no-store'});st=await r.json();if(!r.ok)throw Error(st.error||'Status nicht verfügbar.')}catch(e){box.innerHTML=`<p class="auth-message error">${esc(e.message)}</p>`;return}
window.__iaPro=!!st.pro;window.__iaTier=st.tier||'free';window.__iaFeat=st.features||{};document.querySelectorAll('.pdf-btn').forEach(x=>{if(x.dataset.pdf)x.hidden=false});const plan=st.pro?(st.proSource==='subscription'?'Investor Pro (monatlich)':`Investor Pro bis ${new Date(st.proUntil).toLocaleDateString('de-DE')}`):st.starter?(st.starterUntil?`Käufer-Pass bis ${new Date(st.starterUntil).toLocaleDateString('de-DE')}`:'Käufer-Pass'):'Kostenlos';
box.innerHTML=`${c.testMode?'<p class="test-note">Testmodus: Es werden keine echten Zahlungen ausgeführt (Testkarte 4242 4242 4242 4242). Gekaufte Kreditmappen werden im Testmodus nicht berechnet.</p>':''}${q.get('checkout')==='success'?'<p class="auth-message">Vielen Dank – Ihre Zahlung wurde übermittelt. Die Rechnung erhalten Sie per E-Mail.</p>':''}<table class="bill-table"><tr><td>Aktueller Tarif</td><td>${plan}</td></tr><tr><td>Kreditmappen-Guthaben</td><td>${st.pro?'unbegrenzt (Pro)':`${Math.max(0,(st.creditMaps||0)-(st.creditMapsUsed||0))} von ${st.creditMaps||0} frei`}</td></tr></table><p><a class="btn btn-outline" href="#angebot">Angebote und Preise ansehen</a></p>${st.hasCustomer?'<p><button class="btn btn-ghost" id="portalBtn">Rechnungen, Zahlungsmittel und Abo verwalten</button></p>':''}`;
/* Nur die Knöpfe im eigenen Abrechnungs-Bereich – die Angebotskarten öffnen den Kaufdialog (app-shell.mjs) und dürfen nicht überschrieben werden. */box.querySelectorAll('[data-buy]').forEach(b=>b.onclick=async()=>{const bc=document.getElementById('billConsent');if(!bc){const P=await fetch('/data/preise.json').then(r=>r.json()).catch(()=>null),o=P&&P.privat&&P.privat.plans.find(x=>x.id===b.dataset.buy);if(o){(await import('/src/buy.mjs?v=892f3666')).openBuy(o);return}location.href='/app/dashboard?buy='+encodeURIComponent(b.dataset.buy)+'#angebot';return}if(!bc.checked){alert('Bitte zuerst der sofortigen Bereitstellung zustimmen.');return}b.disabled=true;try{const r=await fetch('/api/billing/checkout',{method:'POST',headers:{...H,'content-type':'application/json'},body:JSON.stringify({plan:b.dataset.buy,consent:true})}),j=await r.json();if(!r.ok)throw Error(j.error||'Checkout fehlgeschlagen.');location.href=j.url}catch(e){alert(e.message);b.disabled=false}});
const pb=document.getElementById('portalBtn');if(pb)pb.onclick=async()=>{pb.disabled=true;try{const r=await fetch('/api/billing/portal',{method:'POST',headers:H}),j=await r.json();if(!r.ok)throw Error(j.error||'Portal nicht verfügbar.');location.href=j.url}catch(e){alert(e.message);pb.disabled=false}}}
// Passwort vergessen: Link per E-Mail anfordern. Antwort ist immer neutral (keine Auskunft, ob ein Konto existiert).
function forgotPage(){const biz=new URLSearchParams(location.search).get('bereich')==='b2b';shell(biz?'Passwort zurücksetzen – Unternehmensportal':'Passwort zurücksetzen','Wir senden Ihnen einen Link, mit dem Sie ein neues Passwort festlegen.',`<section class="section"><div class="container"><div class="auth-card"><form id="authForm"><label>E-Mail<input id="email" type="email" autocomplete="email" required></label><button class="btn btn-primary btn-lg" type="submit">Link anfordern</button><div id="authMessage" class="auth-message" hidden></div></form><div class="auth-links"><a href="${biz?'/business-portal':'/auth/login'}">Zurück zur Anmeldung</a></div></div></div></section>`);
document.querySelector('#authForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;msg('Bitte warten …');try{const im=await iaMail({action:'recover',email:email.value.trim().toLowerCase(),...(biz?{next:'/business-portal'}:{})});if(im){if(im.status===429)throw Error('Zu viele Anfragen. Bitte in einigen Minuten erneut versuchen.');if(!im.ok)throw Error(im.d.error||'Bitte die E-Mail-Adresse prüfen.');msg('Falls ein Konto mit dieser Adresse besteht, ist eine E-Mail von LeaseRun unterwegs. Bitte auch den Spam-Ordner prüfen. Der Link ist nur kurze Zeit gültig.','success');return}const r=await api('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+'/auth/reset'),{method:'POST',body:JSON.stringify({email:email.value.trim().toLowerCase()})});if(r.status===429)throw Error('Zu viele Anfragen. Bitte in einigen Minuten erneut versuchen.');msg('Falls ein Konto mit dieser Adresse besteht, ist der Link unterwegs. Bitte auch den Spam-Ordner prüfen. Der Link ist nur kurze Zeit gültig.','success')}catch(err){msg(err.message,'error');b.disabled=false}}}
// Neues Passwort setzen: Token kommt aus dem Link (#access_token=…&type=recovery).
function resetPage(){const h=new URLSearchParams(location.hash.slice(1)),tok=h.get('access_token'),err=h.get('error_description'),biz=h.get('bereich')==='b2b';
if(!tok){shell('Neues Passwort','Link ungültig',`<section class="section"><div class="container"><div class="auth-card"><div class="auth-message error">${esc(err?err.replace(/\+/g,' '):'Der Link ist ungültig oder abgelaufen.')} Bitte <a href="${h.get('bereich')==='creator'?'/creators#passwort':'/auth/forgot'+(biz?'?bereich=b2b':'')}">einen neuen Link anfordern</a>.</div></div></div></section>`);return}
history.replaceState(null,'',location.pathname);
shell('Neues Passwort','Bitte legen Sie ein neues Passwort mit mindestens 8 Zeichen fest.',`<section class="section"><div class="container"><div class="auth-card"><form id="authForm"><label>Neues Passwort<input id="pw1" type="password" minlength="8" autocomplete="new-password" required></label><label>Passwort wiederholen<input id="pw2" type="password" minlength="8" autocomplete="new-password" required></label><button class="btn btn-primary btn-lg" type="submit">Passwort speichern</button><div id="authMessage" class="auth-message" hidden></div></form></div></div></section>`);
document.querySelector('#authForm').onsubmit=async e=>{e.preventDefault();if(pw1.value!==pw2.value){msg('Die Passwörter stimmen nicht überein.','error');return}msg('Bitte warten …');try{const r=await api('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:pw1.value})},tok);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.msg||d.error_description||'Passwort konnte nicht gespeichert werden.');const sess={access_token:tok,refresh_token:h.get('refresh_token'),expires_in:Number(h.get('expires_in'))||3600,token_type:'bearer',user:d};if(h.get('bereich')==='creator'){try{sess.expires_at=Math.floor(Date.now()/1000)+sess.expires_in;localStorage.setItem('leaserun-creator-session-v1',JSON.stringify(sess));localStorage.setItem('lr-last-active-creator',String(Date.now()))}catch{}msg('Passwort gespeichert. Du wirst in den Creator-Bereich weitergeleitet …','success');setTimeout(()=>location.href='/creators',900);return}if(biz){try{localStorage.setItem('leaserun-b2b-session-v1',JSON.stringify(sess));localStorage.setItem('lr-last-active-b2b',String(Date.now()))}catch{}msg('Passwort gespeichert. Sie werden ins Unternehmensportal weitergeleitet …','success');setTimeout(()=>location.href='/business-portal',900);return}set(sess);msg('Passwort gespeichert. Sie werden weitergeleitet …','success');setTimeout(()=>location.href='/app/dashboard',900)}catch(er){msg(er.message,'error')}}}
