// Gesamtdossier (Kreditmappe + hochgeladene Unterlagen) für Unternehmenskonten mit Pro/Enterprise.
async function gesamtBtn(m,vid){const T=()=>{try{return JSON.parse(localStorage.getItem('leaserun-auth-session-v1')||'null')?.access_token||''}catch{return ''}};let acc=null;try{const r=await fetch('/api/b2b/account',{headers:{Authorization:'Bearer '+T()},cache:'no-store'});acc=r.ok?await r.json():null}catch{acc=null}
if(!acc||!acc.limits||!acc.limits.merger)return;const b=document.createElement('button');b.type='button';b.className='btn btn-outline';b.style.marginTop='8px';b.textContent='Gesamtdossier mit Unterlagen (PDF)';m.append(document.createElement('br'),b);
b.onclick=async()=>{b.disabled=true;b.textContent='Wird zusammengeführt …';try{const r=await fetch('/api/kreditmappe/gesamt',{method:'POST',headers:{Authorization:'Bearer '+T(),'content-type':'application/json'},body:JSON.stringify({versionId:vid})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'Fehler');location.href=j.url;b.textContent='Gesamtdossier erstellt ('+j.pages+' Seiten'+(j.skipped?', '+j.skipped+' Datei(en) nicht eingebunden – siehe Anlagenverzeichnis':'')+')'}catch(e){b.textContent=e.message;b.disabled=false}}}

// Objektgrenze je Tarif (im Browser geprüft): kostenlos 3, Einsteiger 10, Profi und Unternehmenskonten mit Tarif unbegrenzt.
function objLimit(){const f=(window.__iaFeat||{}).objekte;if(window.__iaB2B||f==='on')return Infinity;if(f==='off')return 2;if(window.__iaPro||window.__iaTier==='starter')return Infinity;return 2}
(()=>{try{const t=JSON.parse(localStorage.getItem('leaserun-auth-session-v1')||'null')?.access_token;if(!t||!location.pathname.startsWith('/app/'))return;fetch('/api/b2b/account',{headers:{Authorization:'Bearer '+t},cache:'no-store'}).then(r=>r.ok?r.json():null).then(d=>{window.__iaB2B=!!(d&&d.tier)}).catch(()=>{})}catch{}})();

// Kaufwunsch von „Jetzt buchen“: Hinweis auf der Anmeldeseite, dass es danach direkt zur Bezahlung geht.
(function buyNote(n){try{const x=JSON.parse(localStorage.getItem('lr-buy-intent')||'null');if(!x||Date.now()-x.at>1800000||!/^\/auth\/(login|register)/.test(location.pathname))return;const c=document.querySelector('.auth-card');if(!c){if(n<20)setTimeout(()=>buyNote(n+1),150);return}if(c.querySelector('.buy-resume'))return;const p=document.createElement('p');p.className='buy-resume';p.textContent='Nach der Anmeldung geht es direkt weiter zur sicheren Bezahlung: '+(x.name||'Ihre Auswahl')+'.';c.prepend(p)}catch{}})(0);
